from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'maths','whats-in-a-name','What\'s in a Name?',
 ('Deba, Deep and their cows','A long time ago, Deba and Deep took their family\'s cows out to graze every day. One day Deba asked how they could be sure no cow was lost, but they did not know how to count. A friend told them to make a mark on the wall for each cow that left, and strike out a mark for each cow that came back. This chapter is about counting, names and grouping things.'),
 [('Counting without numbers',['Deba and Deep made one mark on the wall for each cow that left the gate. When the cows came home, they struck out one mark for each cow that entered.','When all marks are struck out, every cow has come home. If two marks are left, two cows are still missing, so they went to search for them and found them in a field.','Tally marks keep track of a count without using number names. We can match one mark with one cow. This idea is called one-to-one matching.','We can use marks to keep track of different things, such as 36 cows and 23 sheep, by making separate rows of marks.']),
  ('Names and number names',['Names are made of letters, and we can count the letters in a name. In a game, the animal with the longest name, the one with the most letters, is the captain of the first team, and the one with the shortest name is the captain of the second team.','Among tiger, snake, dog, lion, goat, elephant, ox, deer, monkey and rat, the longest name is elephant with 8 letters, and the shortest name is ox with 2 letters.','Numbers have names too. 43 is forty-three, and the number name has 10 letters, 5 in forty and 5 in three. 17 is seventeen, and its number name has 9 letters.','56 is fifty-six, and it has 8 letters. Other numbers between 1 and 99 that also have 8 letters are 13, 14, 18, 19, 41, 42, 46, 51, 52, 61, 62 and 66.','Among the numbers from 1 to 99, the longest names are seventy-three, seventy-seven and seventy-eight, with 12 letters each. The shortest names are one, two, six and ten, with 3 letters each.']),
  ('Sorting and grouping',['We can group things in different ways. The animal cards can be grouped as those that eat food and those that do not, or by the number of legs.','There is more than one correct way to group. Every object must belong to exactly one group.','Household things can be grouped as things that need electricity, such as a TV, lamp, fan and clock, and things that do not, such as a chair, bed, pillow and blanket.','A group can be made by looking at what is common, such as having four legs, being a thing in the kitchen, or beginning with the same letter.']),
  ('Collecting information',['We can collect information about our class. We can count how many children have the same starting letter in their names, or the same ending letter.','We can look at hair styles. Some children have two ponytails, some have one plait and some have short hair. We count each kind and write the numbers.','The most common starting letter is the one with the most names.','Names of places can be long. Venkatanarasimharajuvaripeta in Andhra Pradesh is a place in India with a very long name.'])],
 [('Deba and Deep made 7 marks when 7 cows left. Five marks were struck out when the cows came back. How many cows are still out?',[('Each mark stands for one cow.','One-to-one matching.'),('Marks left = 7 - 5 = 2.','Take away the struck-out marks.'),('Two cows are still out.','They went to search for them.')]),
  ('How many letters are in forty-three?',[('Forty has 5 letters: f, o, r, t, y.','Count each part.'),('Three has 5 letters: t, h, r, e, e.','Count the second part.'),('5 + 5 = 10 letters.','Add the two counts.')]),
  ('Group these things: TV, chair, fan, bed. Use the idea of electricity.',[('TV and fan need electricity.','Check each thing.'),('Chair and bed do not need electricity.','They work without it.'),('Two groups: needs electricity and does not.','Every object is in one group.')])],
 ('Explain how Deba and Deep made sure every cow came back.',['A mark for each cow leaving','Strike out a mark for each cow returning','Marks left show missing cows','One-to-one matching'],['They counted using number names','They needed to count every cow aloud']),
 ['We can count by making one mark for each thing, called one-to-one matching.','Names have letters and numbers have names, and we can count the letters.','Things can be grouped in more than one way.','Every object must be in exactly one group.','We can collect information about our class and count it.'],
 [M('1',1,'How did Deba and Deep keep track of the cows?','Made a mark for each cow',[('Counted aloud','They did not know how to count'),('Tied them together','The story is about marks')],'One mark for each cow.'),
  M('2',1,'What was left on the wall when two cows were missing?','Two marks',[('No marks','Then no cows missing'),('Ten marks','Marks left equals missing cows')],'Two marks mean two cows.'),
  N('3',1,'How many letters in the word elephant?',8,'e, l, e, p, h, a, n, t.',[(7,'Count again'),(9,'Count again')]),
  N('4',1,'How many letters are in seventeen?',9,'s, e, v, e, n, t, e, e, n.',[(8,'Count again'),(10,'Count again')]),
  N('5',2,'How many letters are in forty-three?',10,'Forty 5 and three 5.',[(9,'Count again'),(8,'Count again')]),
  N('6',2,'How many letters are in fifty-six?',8,'Fifty 5 and six 3.',[(9,'Count again'),(7,'Count again')]),
  M('7',2,'Which animal in the list has the shortest name?','ox',[('dog','dog has 3 letters'),('rat','rat has 3 letters')],'ox has 2 letters.'),
  M('8',2,'Which number has the longest name between 1 and 99?','seventy-seven',[('one','one is very short'),('fifty','fifty is short')],'Seventy-seven has 12 letters.'),
  F('9',2,'Things can be grouped in only one correct way.',False,'There are many ways to group.'),
  M('10',2,'Which thing needs electricity?','Fan',[('Chair','A chair does not'),('Pillow','A pillow does not')],'A fan runs on electricity.'),
  M('11',3,'What does matching one mark with one cow help us find?','Whether any cow is missing',[('How tall the cows are','Marks do not show height'),('The colour of cows','Marks do not show colour')],'Leftover marks show missing cows.'),
  N('12',3,'There are 36 cows and 23 sheep. How many marks are needed to keep track of both?',59,'36 + 23 = 59.',[(13,'That is 36 - 23'),(58,'Add the ones: 6 + 3 = 9')])],
 keep=['tally','group','one-to-one matching'])
